package content

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
)

// catalogMeta mirrors the manifest generated by the Python ETL
// (scripts/sync_sources.py build) into data/api/catalog-meta.json.
type catalogMeta struct {
	Entities   int            `json:"entities"`
	Translated int            `json:"translated"`
	ByCategory map[string]int `json:"by_category"`
}

func TestBundledCatalogSchemaAndCoverage(t *testing.T) {
	root := filepath.Join("..", "..")
	records, err := LoadDir(filepath.Join(root, "data", "catalog"))
	if err != nil {
		t.Fatal(err)
	}
	if err = ValidateSchema(records, filepath.Join(root, "data", "schema", "entity.schema.json")); err != nil {
		t.Fatal(err)
	}

	metaBytes, err := os.ReadFile(filepath.Join(root, "data", "api", "catalog-meta.json"))
	if err != nil {
		t.Fatal(err)
	}
	var meta catalogMeta
	if err := json.Unmarshal(metaBytes, &meta); err != nil {
		t.Fatal(err)
	}

	if len(records) != meta.Entities {
		t.Fatalf("expected %d bundled entities per catalog-meta.json, got %d", meta.Entities, len(records))
	}
	english, russianNames, russianFull := 0, 0, 0
	categoryCounts := map[string]int{}
	for _, record := range records {
		categoryCounts[record.Category]++
		if _, ok := record.Translations["en"]; ok {
			english++
		}
		if russian, ok := record.Translations["ru"]; ok {
			russianNames++
			if russian.Description != "" {
				russianFull++
			}
		}
	}
	for category, expected := range meta.ByCategory {
		if categoryCounts[category] != expected {
			t.Errorf("expected %d %s records, got %d", expected, category, categoryCounts[category])
		}
	}
	if english != meta.Entities {
		t.Fatalf("expected every record to carry an English translation: en=%d of %d", english, meta.Entities)
	}
	// The publishing pipeline never emits a Russian name without a Russian
	// description; name-only matches stay in the translated layer only.
	if russianNames != russianFull {
		t.Fatalf("published catalog has name-only Russian translations: names=%d full=%d", russianNames, russianFull)
	}
	if russianFull != meta.Translated {
		t.Fatalf("expected %d records with Russian text per catalog-meta.json, got %d", meta.Translated, russianFull)
	}
}

func TestLoadDirRejectsTrailingJSON(t *testing.T) {
	dir := t.TempDir()
	data := `[] []`
	if err := os.WriteFile(filepath.Join(dir, "records.json"), []byte(data), 0600); err != nil {
		t.Fatal(err)
	}
	if _, err := LoadDir(dir); err == nil {
		t.Fatal("trailing JSON was accepted")
	}
}
